public class Evento {
    // Atributos, i.e., info de los eventos
    private String descripcion;
    private String tipo;
    private boolean exitoso;

    // valores default
    public Evento() {
        descripcion = "";
        tipo = "";
        exitoso = false;
    }

	//Constructor con datos

    public Evento(String descripcion, String tipo, boolean exitoso) {
        this.descripcion = descripcion;
        this.tipo = tipo;
        this.exitoso = exitoso;
    }


    // Setters y getters respectivos

    public void setDescripcion(String newDescripcion) {
        descripcion = newDescripcion;
    }

    public String getDescripcion() {
        return descripcion;
    }


    public void setTipo(String newTipo) {
        tipo = newTipo;
    }

    public String getTipo() {
        return tipo;
    }


    public void setExitoso(boolean newExitoso) {
        exitoso = newExitoso;
    }

    public boolean getExitoso() {
        return exitoso;
    }

    // Override del toString

    @Override
    public String toString() {
		//Mostrar los resultados y el estado.
        String resultado;
        if (exitoso) {
            resultado = "Exitoso";
        }
        else {
            resultado = "Fallido";
        }

        return "Tipo: " + tipo
            + "\nDescripcion: " + descripcion
            + "\nResultado: " + resultado;
    }
}
